// GF(2) test: is the cochain omega|_D a coboundary on the subcomplex D generated by a set of facets?
// One "class" = (degree j, omega on j-simplices, boundary incidence of j-simplices on (j-1)-simplices).
#include <cstdint>
#include <vector>
#include <algorithm>
using namespace std;
struct Cls {
    int nj, nm, j, W, cur = 0;
    vector<uint8_t> omega;
    vector<int> bd, fs_off, fs, stamp;
    vector<vector<uint64_t>> piv;
    vector<char> hasPiv;
    vector<uint8_t> pivRhs;
};
static vector<Cls*> G;
extern "C" {
int add_class(int j, int nj, int nm, const uint8_t* omega, const int* bd, int nf,
              const int* fs_off, const int* fs) {
    Cls* c = new Cls();
    c->j = j; c->nj = nj; c->nm = nm;
    c->omega.assign(omega, omega + nj);
    c->bd.assign(bd, bd + (size_t)nj * (j + 1));
    c->fs_off.assign(fs_off, fs_off + nf + 1);
    c->fs.assign(fs, fs + fs_off[nf]);
    c->stamp.assign(nj, 0);
    c->W = (nm + 63) / 64;
    c->piv.assign(nm, vector<uint64_t>());
    c->hasPiv.assign(nm, 0);
    c->pivRhs.assign(nm, 0);
    G.push_back(c);
    return (int)G.size() - 1;
}
// 1 if balanced (omega|_D is a coboundary), 0 otherwise
int balanced(int ci, const uint8_t* inD, int nf) {
    Cls* c = G[ci];
    c->cur++;
    fill(c->hasPiv.begin(), c->hasPiv.end(), 0);
    vector<uint64_t> row(c->W);
    for (int f = 0; f < nf; ++f) {
        if (!inD[f]) continue;
        for (int p = c->fs_off[f]; p < c->fs_off[f + 1]; ++p) {
            int s = c->fs[p];
            if (c->stamp[s] == c->cur) continue;
            c->stamp[s] = c->cur;
            fill(row.begin(), row.end(), 0);
            const int* b = &c->bd[(size_t)s * (c->j + 1)];
            for (int t = 0; t <= c->j; ++t) row[b[t] >> 6] ^= (1ULL << (b[t] & 63));
            uint8_t rhs = c->omega[s];
            while (true) {
                int lead = -1;
                for (int w = c->W - 1; w >= 0; --w)
                    if (row[w]) { lead = w * 64 + 63 - __builtin_clzll(row[w]); break; }
                if (lead < 0) { if (rhs) return 0; break; }
                if (c->hasPiv[lead]) {
                    const vector<uint64_t>& pr = c->piv[lead];
                    for (int w = 0; w < c->W; ++w) row[w] ^= pr[w];
                    rhs ^= c->pivRhs[lead];
                } else {
                    c->hasPiv[lead] = 1; c->piv[lead] = row; c->pivRhs[lead] = rhs; break;
                }
            }
        }
    }
    return 1;
}
}
